"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { Bell, CalendarDays, ChevronLeft, ChevronRight, CircleDollarSign, Clock3, Download, LayoutDashboard, MessageCircle, Moon, Phone, Plus, Search, Send, Settings, Sun, UserRound, WalletCards, X } from "lucide-react";
import { addDays, format, isSameDay, startOfDay } from "date-fns";
import { ru } from "date-fns/locale";
import styles from "./page.module.css";

declare global { interface Window { Telegram?: { WebApp?: { initData: string; ready: () => void; expand: () => void; BackButton?: { show: () => void; hide: () => void; onClick: (callback: () => void) => void } } } } }
type Asset = { id: string; name: string; category: string; dailyRate: string | number; status: string; currentMileage?: number | null; serviceMileage?: number | null; oilChangeMileage?: number | null; variatorServiceMileage?: number | null; lastServiceDate?: string | null; serviceNote?: string | null; rentalConditions?: string | null; statusColor?: string };
type Booking = { id: string; assetId: string; clientName: string; clientPhone?: string; startDate: string; endDate: string; startTime?: string; endTime?: string; createdAt?: string; updatedAt?: string; dailyRate?: string | number; totalPrice: string | number; paidAmount: string | number; depositAmount?: string | number; status: string; asset?: Asset };
type Tab = "calendar" | "bookings" | "analytics" | "profile"; type Partner = { id: string; name: string; contactName?: string | null; phone?: string | null; contactChannel?: "PHONE" | "WHATSAPP" | "TELEGRAM"; email?: string | null; commissionType: string; commissionValue: string | number }; type TeamMember = { id: string; name: string; telegramId: string; phone?: string | null; email?: string | null; commissionPercent?: number; role: string; active: boolean };
const displayAssetName = (name: string) => name.replace(/^SYM\s+/i, "").trim();
function AssetLabel({ name }: { name: string }) { const label = displayAssetName(name); const match = label.match(/^(.*?)(\d+\s*cc\s*\([^)]*\))$/i); return match ? <>{match[1]}<strong className={styles.assetNumber}>{match[2]}</strong></> : label; }
const statusColors: Record<string, string> = { CONFIRMED: "blue", PENDING: "pink", PAID: "green", ACTIVE: "green", TECHNICAL: "yellow", CANCELLED: "gray" };

type Analytics = { revenue: number; deposits: number; expenses: number; net: number; expected: number; bookings: number; commissionPercent?: number; commission?: number; isManager?: boolean; todayReturns?: Array<{ id: string; clientName: string; assetName: string; time: string; status: string }>; todayPickups?: Array<{ id: string; clientName: string; assetName: string; time: string; status: string }>; upcomingPayments?: Array<{ id: string; clientName: string; assetName: string; amount: number; date: string }>; serviceAssets?: Array<{ id: string; name: string; status: string; currentMileage: number | null; serviceMileage: number | null; serviceNote: string | null }>; rentalDays?: number; blockedDays?: number; byAsset?: Array<{ assetId: string; name: string; rentalDays: number; blockedDays: number; income: number; expenses: number; profit: number; bookings: number; monthlyIdle?: number }> };
const initialAnalytics: Analytics = { revenue: 0, deposits: 0, expenses: 0, net: 0, expected: 0, bookings: 0, rentalDays: 0, blockedDays: 0, byAsset: [], todayReturns: [], todayPickups: [], upcomingPayments: [], serviceAssets: [] };

export default function Home() {
  const [tab, setTab] = useState<Tab>("calendar"); const [bookingView, setBookingView] = useState<"active" | "past" | "archive">("active"); const [archivedBookings, setArchivedBookings] = useState<Booking[]>([]); const [darkMode, setDarkMode] = useState(false); const [bookingSeed, setBookingSeed] = useState<{ assetId: string; startDate: string; endDate: string } | null>(null); const [calendarSelection, setCalendarSelection] = useState<{ assetId: string; date: string } | null>(null); const [loggingOut, setLoggingOut] = useState(false); const [editingAsset, setEditingAsset] = useState<Asset | null>(null); const [showGuide, setShowGuide] = useState(false); const [partners, setPartners] = useState<Partner[]>([]); const [team, setTeam] = useState<TeamMember[]>([]); const [dragAsset, setDragAsset] = useState<string | null>(null); const [assets, setAssets] = useState<Asset[]>([]); const [bookings, setBookings] = useState<Booking[]>([]); const [analytics, setAnalytics] = useState(initialAnalytics); const [search, setSearch] = useState(""); const [reportPartner, setReportPartner] = useState(""); const [reportFrom, setReportFrom] = useState(""); const [reportTo, setReportTo] = useState(""); const [profileSearch, setProfileSearch] = useState(""); const [assetSearch, setAssetSearch] = useState(""); const [editingPartner, setEditingPartner] = useState<Partner | null>(null); const [editingTeam, setEditingTeam] = useState<TeamMember | null>(null); const [modal, setModal] = useState<"booking" | "asset" | "payment" | "partner" | "team" | null>(null); const [selectedBooking, setSelectedBooking] = useState<Booking | null>(null); const [toast, setToast] = useState(""); const [selectedAssetAnalytics, setSelectedAssetAnalytics] = useState<string | null>(null); const [notificationCenterOpen, setNotificationCenterOpen] = useState(false); const [notificationPrefsOpen, setNotificationPrefsOpen] = useState(false); const [notificationPrefs, setNotificationPrefs] = useState({ returns: true, pickups: true, service: true, payments: true }); const [dismissedNotifications, setDismissedNotifications] = useState<string[]>([]); const [authRequired, setAuthRequired] = useState(false); const [loading, setLoading] = useState(true); const [calendarOffset, setCalendarOffset] = useState(0); const [calendarScale, setCalendarScale] = useState("normal"); const calendarDays = useMemo(() => { const today = startOfDay(new Date()); const maxEnd = bookings.reduce((max, booking) => { const end = new Date(booking.endDate); return end > max ? end : max; }, today); return Math.min(366, Math.max(31, Math.ceil((maxEnd.getTime() - today.getTime()) / 86400000) + 4)); }, [bookings]); const days = useMemo(() => Array.from({ length: calendarDays }, (_, index) => addDays(startOfDay(new Date()), index - 3 + calendarOffset * 31)), [calendarDays, calendarOffset]);
  const api = useCallback(async (path: string, options?: RequestInit) => { const initData = window.Telegram?.WebApp?.initData; const headers = new Headers(options?.headers); headers.set("content-type", "application/json"); if (initData) headers.set("x-telegram-init-data", initData); const response = await fetch(path, { ...options, cache: "no-store", credentials: "include", headers }); const body = await response.json().catch(() => ({})); if (!response.ok) { if (response.status === 401) setAuthRequired(true); throw new Error(body.error || "Не удалось выполнить действие"); } return body; }, []);
  const refresh = useCallback(async () => { setLoading(true); const results = await Promise.allSettled([api("/api/assets"), api("/api/bookings"), api("/api/analytics"), api("/api/partners"), api("/api/team")]); const [a, b, c, p, t] = results; if (a.status === "fulfilled") setAssets(a.value); if (b.status === "fulfilled") setBookings(b.value); if (c.status === "fulfilled") setAnalytics(c.value); if (p.status === "fulfilled") setPartners(p.value); if (t.status === "fulfilled") setTeam(t.value); if (results.every(result => result.status === "fulfilled")) setAuthRequired(false); setLoading(false); }, [api]);
  useEffect(() => { const savedTheme = window.localStorage.getItem("rp_theme"); if (savedTheme === "dark") setDarkMode(true); const savedScale = window.localStorage.getItem("rp_calendar_scale"); if (savedScale) setCalendarScale(savedScale); const savedNotifications = window.localStorage.getItem("rf_notification_prefs"); if (savedNotifications) { try { setNotificationPrefs(current => ({ ...current, ...JSON.parse(savedNotifications) })); } catch {} } const savedDismissed = window.localStorage.getItem("rf_dismissed_notifications"); if (savedDismissed) { try { setDismissedNotifications(JSON.parse(savedDismissed)); } catch {} } const webApp = window.Telegram?.WebApp; if (webApp) { webApp.ready(); webApp.expand(); } void refresh(); }, [refresh]);
  useEffect(() => { if (tab === "bookings" && bookingView === "archive") void api("/api/bookings?archived=true").then(setArchivedBookings).catch(() => setArchivedBookings([])); }, [tab, bookingView, api]);
  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(""), 3500); return () => window.clearTimeout(timer); }, [toast]);
  useEffect(() => { document.body.style.overflow = modal || notificationCenterOpen ? "hidden" : ""; return () => { document.body.style.overflow = ""; }; }, [modal, notificationCenterOpen]);
  const notificationItems = { returns: notificationPrefs.returns ? (analytics.todayReturns ?? []).filter(item => !dismissedNotifications.includes(`returns:${item.id}`)) : [], pickups: notificationPrefs.pickups ? (analytics.todayPickups ?? []).filter(item => !dismissedNotifications.includes(`pickups:${item.id}`)) : [], service: notificationPrefs.service ? (analytics.serviceAssets ?? []).filter(item => !dismissedNotifications.includes(`service:${item.id}`)) : [], payments: notificationPrefs.payments ? (analytics.upcomingPayments ?? []).filter(item => !dismissedNotifications.includes(`payments:${item.id}`)) : [] }; const notificationCount = notificationItems.returns.length + notificationItems.pickups.length + notificationItems.service.length + notificationItems.payments.length; const dismissNotification = (key: string) => { const next = [...dismissedNotifications, key]; setDismissedNotifications(next); window.localStorage.setItem("rf_dismissed_notifications", JSON.stringify(next)); }; const visibleBookings = bookingView === "archive" ? archivedBookings : bookings; const filteredBookings = useMemo(() => visibleBookings.filter(b => `${b.clientName} ${b.asset?.name ?? ""}`.toLowerCase().includes(search.toLowerCase())), [visibleBookings, search]);
  const currency = (value: string | number) => `${Number(value).toLocaleString("vi-VN")} ₫`;
  const downloadReport = async () => { try {
    const selectedPartner = reportPartner.trim();
    const params = new URLSearchParams(); if (selectedPartner) params.set("partner", selectedPartner); if (reportFrom) params.set("from", reportFrom); if (reportTo) params.set("to", reportTo);
    const report = await api(`/api/reports${params.toString() ? `?${params.toString()}` : ""}`);
    const esc = (value: unknown) => String(value ?? "—").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;");
    const dateOnly = (value: unknown) => { const raw = String(value ?? "").slice(0, 10); if (!raw) return "—"; const [year, month, day] = raw.split("-"); return `${day}.${month}.${year.slice(2)}`; };
    const moneyReport = (value: unknown, unit = "₫") => `${Number(value || 0).toLocaleString("vi-VN")} ${unit}`;
    const bookings = (report.bookings || []) as Array<Record<string, unknown>>;
    const cards = bookings.map((booking, index) => `<article class="rental-card"><div class="rental-brand"><b>KARMA RENT</b><span>Карточка аренды · ${index + 1}</span></div><div class="rental-title"><h2>Аренда</h2><span>${esc(dateOnly(booking.startDate))}</span></div><div class="rental-hero"><b>${esc(booking.clientPhone || booking.clientName)}</b><strong>Байк: ${esc(booking.assetName)}</strong>${booking.partner && booking.partner !== "Без партнёра" ? `<span>Партнёр: ${esc(booking.partner)}</span>` : ""}</div><div class="rental-grid"><div><small>Дни</small><b>${Math.max(1, Math.ceil((new Date(`${String(booking.endDate).slice(0,10)}T${booking.endTime || "12:00"}`).getTime() - new Date(`${String(booking.startDate).slice(0,10)}T${booking.startTime || "12:00"}`).getTime()) / 86400000))}</b></div><div><small>Дата</small><b>${esc(dateOnly(booking.startDate))}</b></div><div><small>Сдача</small><b>${esc(dateOnly(booking.endDate))}</b></div><div><small>Время</small><b>${esc(`${booking.startTime || "12:00"} — ${booking.endTime || "12:00"}`)}</b></div><div><small>Фото паспорта</small><b>${booking.passportPhoto ? "+" : "—"}</b></div><div><small>Лимит километража по городу</small><b>${booking.mileageLimitPerDay ? `${esc(booking.mileageLimitPerDay)} км/сутки` : "—"}</b></div><div><small>Держатель телефона</small><b>${esc(booking.phoneHolder || "—")}</b></div><div><small>Шлем</small><b>${esc(booking.helmetCount ?? "—")}</b></div><div><small>Пробег</small><b>${esc(booking.mileageAtHandover ?? "—")}</b></div><div><small>Бензин</small><b>${esc(booking.fuelLevel || "—")}</b></div><div><small>Депозит</small><b>${esc(moneyReport(booking.depositAmount, String(booking.depositCurrency || "₫")))}</b></div><div><small>Стоимость</small><b>${esc(moneyReport(booking.dailyRate))} / сутки</b></div></div><div class="rental-total"><span>Стоимость аренды</span><strong>${esc(moneyReport(booking.totalPrice))}</strong></div>${booking.notes ? `<div class="rental-notes"><small>Примечание</small><p>${esc(booking.notes)}</p></div>` : ""}</article>`).join("");
    const total = (report.totals?.income ?? 0) as number;
    const printWindow = window.open("", "_blank"); if (!printWindow) throw new Error("Разрешите всплывающие окна для PDF-отчёта");
    printWindow.document.open(); printWindow.document.write(`<!doctype html><html lang="ru"><head><meta charset="utf-8"><title>KARMA RENT — отчёт по арендам</title><style>*{box-sizing:border-box}body{margin:0;background:#eef4f6;color:#102a43;font:14px Inter,Arial,sans-serif;padding:24px}.report-head{max-width:760px;margin:0 auto 18px;background:#102a43;color:#fff;border-radius:18px;padding:22px 24px}.report-head h1{margin:0 0 6px;font-size:26px}.report-head p{margin:4px 0;color:#c6e1e8}.report-total{float:right;color:#77e6ef;font-size:20px}.rental-card{max-width:760px;margin:0 auto 18px;background:#fff;border:1px solid #d8e6eb;border-radius:18px;padding:20px;box-shadow:0 7px 22px #153b4b12;break-inside:avoid}.rental-brand{display:flex;justify-content:space-between;align-items:center;color:#078eae;font-size:12px;letter-spacing:.08em}.rental-brand span{font-size:11px;color:#8aa0aa;letter-spacing:0}.rental-title{display:flex;justify-content:space-between;align-items:end;border-bottom:1px solid #e8f0f3;padding:18px 0 12px}.rental-title h2{font-size:27px;margin:0;color:#102a43}.rental-title span{color:#7e949e}.rental-hero{display:flex;flex-direction:column;gap:5px;padding:14px 0;color:#102a43}.rental-hero b{font-size:20px}.rental-hero strong{font-size:16px}.rental-hero span{font-size:12px;color:#168da6}.rental-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.rental-grid>div{min-height:64px;background:#f4fafb;border:1px solid #dcecf0;border-radius:10px;padding:9px}.rental-grid small,.rental-grid b{display:block}.rental-grid small{font-size:10px;color:#74909b;margin-bottom:5px}.rental-grid b{font-size:13px;color:#163e52;overflow-wrap:anywhere}.rental-total{display:flex;justify-content:space-between;align-items:center;border-top:2px solid #08a7c6;margin-top:14px;padding-top:13px}.rental-total strong{font-size:20px;color:#078eae}.rental-notes{margin-top:12px;padding:10px 12px;background:#fff9e7;border-radius:9px}.rental-notes small{color:#987c36}.rental-notes p{margin:5px 0 0;white-space:pre-wrap}.print-button{display:block;margin:0 auto 18px;border:0;border-radius:10px;background:#08a7c6;color:#fff;font-weight:800;padding:11px 18px;cursor:pointer}@media(max-width:600px){body{padding:12px}.report-head{padding:17px}.report-head h1{font-size:21px}.report-total{float:none;display:block;margin-top:9px}.rental-card{padding:14px}.rental-grid{grid-template-columns:repeat(2,1fr)}.rental-title h2{font-size:23px}}@media print{body{background:#fff;padding:0}.report-head{box-shadow:none;border-radius:0;max-width:none}.print-button{display:none}.rental-card{box-shadow:none;margin-bottom:12px}}</style></head><body><header class="report-head"><span>KARMA RENT · ${esc(selectedPartner || "Все партнёры")}</span><h1>Отчёт по арендам${selectedPartner ? ` · ${esc(selectedPartner)}` : ""}</h1><p>Сформирован: ${esc(new Date().toLocaleString("ru-RU"))}</p><strong class="report-total">Получено: ${esc(moneyReport(total))}</strong></header><button class="print-button" onclick="window.print()">Печать / сохранить PDF</button>${cards || `<article class="rental-card"><h2>Аренд за выбранный период нет</h2><p>Проверьте имя партнёра и период отчёта.</p></article>`}</body></html>`); printWindow.document.close(); setToast("Отчёт по арендам открыт — нажмите «Печать / сохранить PDF»");
  } catch (error) { setToast(error instanceof Error ? error.message : "Не удалось сформировать отчёт"); } };
  const moveAsset = async (assetId: string, direction: -1 | 1) => { const current = assets.findIndex(item => item.id === assetId); const target = current + direction; if (current < 0 || target < 0 || target >= assets.length) return; const next = [...assets]; const [item] = next.splice(current, 1); next.splice(target, 0, item); setAssets(next); try { await Promise.all(next.map((entry, index) => api("/api/assets", { method: "PATCH", body: JSON.stringify({ id: entry.id, sortOrder: index }) }))); setToast("Порядок сохранён"); } catch (error) { setToast(error instanceof Error ? error.message : "Не удалось сохранить порядок"); await refresh(); } };
  const reorder = async (targetId: string) => { if (!dragAsset || dragAsset === targetId) return; const next = [...assets]; const from = next.findIndex(item => item.id === dragAsset); const to = next.findIndex(item => item.id === targetId); const [moved] = next.splice(from, 1); next.splice(to, 0, moved); setAssets(next); try { await Promise.all(next.map((item, index) => api("/api/assets", { method: "PATCH", body: JSON.stringify({ id: item.id, sortOrder: index }) }))); setToast("Порядок объектов сохранён"); } catch (error) { setToast(error instanceof Error ? error.message : "Не удалось сохранить порядок"); await refresh(); } finally { setDragAsset(null); } };
  const bookingStyle = (booking: Booking, lane = 0) => { const first = days[0].getTime(); const dayMs = 86400000; const startAt = new Date(`${booking.startDate.slice(0, 10)}T${booking.startTime || "12:00"}`).getTime(); const endAt = new Date(`${booking.endDate.slice(0, 10)}T${booking.endTime || "12:00"}`).getTime(); const rawStart = (startAt - first) / dayMs; const rawEnd = (endAt - first) / dayMs; const startUnit = Math.max(0, Math.min(days.length, rawStart)); const endUnit = Math.max(startUnit + 0.5, Math.min(days.length, rawEnd)); const span = Math.max(0.5, endUnit - startUnit); return { left: `${(startUnit / days.length) * 100}%`, width: `${(span / days.length) * 100}%`, top: `${6 + (lane % 3) * 30}px` }; };
  const closeModal = () => { setModal(null); setSelectedBooking(null); };
  const title = tab === "calendar" ? format(days[3] || new Date(), "LLLL yyyy", { locale: ru }) : tab === "bookings" ? "Бронирования" : tab === "analytics" ? "Аналитика и финансы" : "Профиль";
  return <main className={`${styles.shell} ${darkMode ? styles.dark : ""} ${styles["calendar-" + calendarScale] || ""}`}>
    <header className={styles.header}><div><p className={styles.eyebrow}>RIDEFLOW RENT</p><h1>{title}</h1></div><div className={styles.headerTools}><button type="button" className={styles.notificationButton} onClick={() => setNotificationCenterOpen(value => !value)} aria-label="Уведомления"><Bell size={18} />{notificationCount > 0 && <span>{notificationCount}</span>}</button><button type="button" className={styles.iconButton} onClick={() => { setDarkMode(value => { const next = !value; window.localStorage.setItem("rp_theme", next ? "dark" : "light"); return next; }); }} aria-label="Сменить тему" title={darkMode ? "Светлая тема" : "Тёмная тема"}>{darkMode ? <Sun size={18} /> : <Moon size={18} />}</button><button className={styles.iconButton} onClick={() => setTab("profile")} aria-label="Настройки" title="Открыть профиль и настройки"><Settings size={18} /></button></div>{notificationCenterOpen && <div className={styles.notificationCenter}><div className={styles.notificationCenterHead}><b>Уведомления</b><button type="button" onClick={() => setNotificationCenterOpen(false)} aria-label="Закрыть уведомления"><X size={16} /></button></div><button type="button" className={styles.notificationSettingsLink} onClick={() => setNotificationPrefsOpen(value => !value)}><Settings size={13} /> Настройки</button>{notificationPrefsOpen && <div className={styles.notificationPrefsPanel}><b>Показывать</b><label><input type="checkbox" checked={notificationPrefs.returns} onChange={e => setNotificationPrefs(v => ({ ...v, returns: e.target.checked }))} /> возвраты</label><label><input type="checkbox" checked={notificationPrefs.pickups} onChange={e => setNotificationPrefs(v => ({ ...v, pickups: e.target.checked }))} /> выдачи</label><label><input type="checkbox" checked={notificationPrefs.service} onChange={e => setNotificationPrefs(v => ({ ...v, service: e.target.checked }))} /> сервис</label><label><input type="checkbox" checked={notificationPrefs.payments} onChange={e => setNotificationPrefs(v => ({ ...v, payments: e.target.checked }))} /> оплаты</label><button type="button" className={styles.notificationSave} onClick={() => { window.localStorage.setItem("rf_notification_prefs", JSON.stringify(notificationPrefs)); setToast("Настройки уведомлений сохранены"); }}>Сохранить</button></div>}{notificationCount ? <div className={styles.notificationCenterList}>{notificationItems.returns.slice(0, 8).map(item => <div className={styles.notificationRow} key={`head-return-${item.id}`}><button type="button" onClick={() => { setTab("calendar"); setNotificationCenterOpen(false); }}><b>Возврат сегодня</b><span>{item.assetName} · {item.clientName}</span></button><button type="button" className={styles.notificationDismiss} onClick={() => dismissNotification(`returns:${item.id}`)} aria-label="Скрыть уведомление"><X size={14} /></button></div>)}{notificationItems.pickups.slice(0, 8).map(item => <div className={styles.notificationRow} key={`head-pickup-${item.id}`}><button type="button" onClick={() => { setTab("calendar"); setNotificationCenterOpen(false); }}><b>Выдача сегодня</b><span>{item.assetName} · {item.clientName}</span></button><button type="button" className={styles.notificationDismiss} onClick={() => dismissNotification(`pickups:${item.id}`)} aria-label="Скрыть уведомление"><X size={14} /></button></div>)}{notificationItems.service.slice(0, 8).map(item => <div className={styles.notificationRow} key={`head-service-${item.id}`}><button type="button" onClick={() => { setTab("profile"); setNotificationCenterOpen(false); }}><b>Нужен сервис</b><span>{item.name} · {item.serviceNote || "проверьте пробег"}</span></button><button type="button" className={styles.notificationDismiss} onClick={() => dismissNotification(`service:${item.id}`)} aria-label="Скрыть уведомление"><X size={14} /></button></div>)}{notificationItems.payments.slice(0, 8).map(item => <div className={styles.notificationRow} key={`head-payment-${item.id}`}><button type="button" onClick={() => { setTab("bookings"); setNotificationCenterOpen(false); }}><b>Ожидается оплата</b><span>{item.assetName} · {item.clientName}</span></button><button type="button" className={styles.notificationDismiss} onClick={() => dismissNotification(`payments:${item.id}`)} aria-label="Скрыть уведомление"><X size={14} /></button></div>)}</div> : <div className={styles.notificationCenterEmpty}>Новых уведомлений нет</div>}</div>}</header>
    {authRequired && <><div className={styles.authNotice}>Войдите через Telegram Mini App или используйте email/пароль владельца.</div><LoginPanel api={api} onDone={async () => { setAuthRequired(false); await refresh(); }} /></>}
    {tab === "calendar" && <section className={styles.content}><div className={styles.toolbar}><button className={styles.roundButton} aria-label="Предыдущие даты" onClick={() => setCalendarOffset(value => value - 1)}><ChevronLeft size={18} /></button><button className={styles.todayButton} onClick={() => setCalendarOffset(0)}>Сегодня</button><button className={styles.roundButton} aria-label="Следующие даты" onClick={() => setCalendarOffset(value => value + 1)}><ChevronRight size={18} /></button><span className={styles.helpWrap}><button className={styles.primaryButton} onClick={() => { setBookingSeed(null); setCalendarSelection(null); setModal("booking"); }}><Plus size={18} /> Бронь</button><HelpTip text="Создаёт новую бронь: выберите байк, клиента, даты и оплату." /></span></div><div className={styles.legend}><span><i className={styles.blueDot} /> подтверждена</span><span><i className={styles.pinkDot} /> ожидает</span><span><i className={styles.greenDot} /> оплачена</span></div><div className={styles.timeline} style={{ "--calendar-days": calendarDays } as React.CSSProperties}><div className={styles.timelineHead}><div className={styles.assetHead}>Объект</div><div className={styles.days}>{days.map(day => <div className={`${styles.day} ${isSameDay(day, new Date()) ? styles.currentDay : ""}`} key={day.toISOString()}><b>{format(day, "d")}</b><small>{format(day, "EEEEE", { locale: ru })}</small></div>)}</div></div>{assets.map(asset => <div className={styles.timelineRow} draggable key={asset.id} onDragStart={() => setDragAsset(asset.id)} onDragOver={e => e.preventDefault()} onDrop={() => void reorder(asset.id)}><div className={styles.assetCell} title={asset.name}><b><AssetLabel name={asset.name} /></b><small aria-hidden="true">{asset.category === "SCOOTER" ? "Скутер" : asset.category === "MOTORCYCLE" ? "Мотоцикл" : asset.category} · {asset.status}</small></div><div className={styles.track}>{days.map(day => <button type="button" className={`${styles.gridCell} ${isSameDay(day, new Date()) ? styles.todayColumn : ""} ${calendarSelection?.assetId === asset.id && calendarSelection.date === format(day, "yyyy-MM-dd") ? styles.selectedCell : ""}`} key={day.toISOString()} aria-label={`Создать бронь: ${asset.name}, ${format(day, "d MMMM", { locale: ru })}`} onClick={() => { const date = format(day, "yyyy-MM-dd"); if (!calendarSelection || calendarSelection.assetId !== asset.id) { setCalendarSelection({ assetId: asset.id, date }); setToast(`Начало аренды: ${format(day, "d MMMM", { locale: ru })}. Выберите дату окончания.`); } else { const start = calendarSelection.date <= date ? calendarSelection.date : date; const finish = calendarSelection.date <= date ? date : calendarSelection.date; setBookingSeed({ assetId: asset.id, startDate: start, endDate: finish }); setCalendarSelection(null); setModal("booking"); } }} />)}{bookings.filter(b => b.assetId === asset.id).map((booking, bookingIndex) => <button className={`${styles.bookingBar} ${styles[statusColors[booking.status] ?? "gray"]} ${new Date(booking.updatedAt || booking.createdAt || booking.startDate).getTime() - new Date(booking.createdAt || booking.startDate).getTime() > 60000 ? styles.editedBooking : ""}`} style={bookingStyle(booking, bookingIndex)} key={booking.id} onClick={event => { event.stopPropagation(); setSelectedBooking(booking); setModal("payment"); }}>{booking.clientName} · {displayAssetName(asset.name)}</button>)}</div></div>)}{assets.length === 0 && <div className={styles.emptyState}><CalendarDays size={24} /><b>{loading ? "Загрузка…" : "Объекты ещё не добавлены"}</b><span>{authRequired ? "Авторизуйтесь внутри Telegram." : "Добавьте первый объект в профиле."}</span></div>}</div></section>}
    {tab === "bookings" && <section className={styles.content}><div className={styles.sectionActions}><div className={styles.searchBox}><Search size={18} /><input placeholder="Поиск клиента или объекта" value={search} onChange={e => setSearch(e.target.value)} /></div><button className={styles.primaryButton} onClick={() => { setBookingSeed(null); setCalendarSelection(null); setModal("booking"); }}><Plus size={17} /> Бронь</button></div><div className={styles.tabs}><button className={bookingView === "active" ? styles.activeTab : ""} onClick={() => setBookingView("active")}>Актуальные</button><button className={bookingView === "past" ? styles.activeTab : ""} onClick={() => setBookingView("past")}>Прошедшие</button><button className={bookingView === "archive" ? styles.activeTab : ""} onClick={() => setBookingView("archive")}>Архив</button></div><div className={styles.cards}>{filteredBookings.map(b => <article className={styles.bookingCard} key={b.id} onClick={() => { setSelectedBooking(b); setModal("payment"); }}><div className={styles.cardTop}><div><b>{b.clientName}</b><span>{b.asset?.name ?? "Объект"}</span></div><em className={styles[`badge_${statusColors[b.status] ?? "gray"}`]}>{b.status === "CONFIRMED" ? "Подтверждена" : b.status}</em></div><div className={styles.cardMeta}><span><Clock3 size={14} /> {format(new Date(b.startDate), "d MMM", { locale: ru })} — {format(new Date(b.endDate), "d MMM", { locale: ru })}</span><strong>{currency(b.totalPrice)}</strong></div><div className={styles.paymentLine}><span>Оплачено {currency(b.paidAmount)}</span><span>Остаток {currency(Number(b.totalPrice) - Number(b.paidAmount))}</span></div>{bookingView === "archive" && <button type="button" className={styles.restoreButton} onClick={async e => { e.stopPropagation(); try { await api("/api/bookings", { method: "PATCH", body: JSON.stringify({ id: b.id, restore: true }) }); setToast("Бронь восстановлена"); const restored = await api("/api/bookings?archived=true"); setArchivedBookings(restored); await refresh(); } catch (err) { setToast(err instanceof Error ? err.message : "Не удалось восстановить бронь"); } }}>Восстановить</button>}</article>)}{filteredBookings.length === 0 && <div className={styles.emptyState}><b>Бронирований нет</b><span>Создайте бронь кнопкой выше.</span></div>}</div></section>}
    {tab === "analytics" && <section className={styles.content}>
      <div className={styles.metricGrid}>
        <Metric title={analytics.isManager ? `Моя комиссия · ${analytics.commissionPercent ?? 0}%` : "Выручка"} value={currency(analytics.isManager ? (analytics.commission ?? 0) : analytics.revenue)} icon={<CircleDollarSign />} accent="cyan" />
        <Metric title="Ожидается" value={currency(analytics.expected)} icon={<Clock3 />} accent="orange" />
        <Metric title={analytics.isManager ? "Объектов в парке" : "Расходы"} value={analytics.isManager ? String(analytics.byAsset?.length ?? 0) : currency(analytics.expenses)} icon={<WalletCards />} accent="pink" />
        <Metric title={analytics.isManager ? "Важных сообщений" : "Чистая прибыль"} value={analytics.isManager ? String(notificationCount) : currency(analytics.net)} icon={<CircleDollarSign />} accent="green" />
      </div>
      <div className={styles.analyticsExplain}><b>Как читать аналитику <HelpTip text="Выручка — полученные платежи. Ожидается — долг клиентов. Расходы — затраты. Прибыль — выручка минус расходы. Простой — свободные дни байка в текущем месяце. Нажмите на строку байка ниже, чтобы открыть детализацию." /></b></div>
      <div className={styles.analyticsSummary}>
        <div><span>Полученные залоги <HelpTip text="Деньги, полученные как залог и ещё не возвращённые клиенту." /></span><b>{currency(analytics.deposits)}</b></div>
        <div><span>Бронирований <HelpTip text="Количество активных и завершённых бронирований без отменённых." /></span><b>{analytics.bookings}</b></div>
        <div><span>Арендных дней <HelpTip text="Суммарное количество дней, когда байки были заняты арендой." /></span><b>{analytics.rentalDays ?? 0}</b></div>
        <div><span>Дней блокировки <HelpTip text="Дни, когда объект был закрыт для аренды из-за ремонта или другой причины." /></span><b>{analytics.blockedDays ?? 0}</b></div>
      </div>
      <div className={styles.panel}>
        <div className={styles.panelTitle}><div><b>Доходность объектов</b><span>Нажмите на байк для выручки, расходов, прибыли, загрузки и бронирований</span></div><input className={styles.inlineSearch} placeholder="Поиск байка" value={assetSearch} onChange={e => setAssetSearch(e.target.value)} />{!analytics.isManager && <><input className={styles.inlineSearch} placeholder="Партнёр для PDF" value={reportPartner} onChange={e => setReportPartner(e.target.value)} /><label className={styles.reportDate}>От<input type="date" value={reportFrom} onChange={e => setReportFrom(e.target.value)} /></label><label className={styles.reportDate}>До<input type="date" value={reportTo} onChange={e => setReportTo(e.target.value)} /></label><button className={styles.reportButton} onClick={() => void downloadReport()}><Download size={15} /> PDF-отчёт</button></>}</div>
        {(analytics.byAsset ?? []).filter(row => row.name.toLowerCase().includes(assetSearch.toLowerCase())).map((row: { assetId: string; name: string; rentalDays: number; blockedDays: number; income: number; expenses: number; profit: number; bookings: number; monthlyIdle?: number }) => <div className={`${styles.assetAnalytics} ${selectedAssetAnalytics === row.assetId ? styles.selectedAssetAnalytics : ""}`} key={row.assetId} role="button" tabIndex={0} onClick={() => setSelectedAssetAnalytics(selectedAssetAnalytics === row.assetId ? null : row.assetId)} onKeyDown={e => { if (e.key === "Enter" || e.key === " ") setSelectedAssetAnalytics(selectedAssetAnalytics === row.assetId ? null : row.assetId); }}><div><b>{row.name}</b><small>{row.bookings} броней · {row.rentalDays} арендных дней · простой в месяце: {row.monthlyIdle ?? 0} дн.</small></div><div><strong>{currency(row.profit)}</strong><small>доход {currency(row.income)} · расходы {currency(row.expenses)}</small></div></div>)}
        {selectedAssetAnalytics && (() => { const row = (analytics.byAsset ?? []).find(item => item.assetId === selectedAssetAnalytics); const assetBookings = bookings.filter(item => item.assetId === selectedAssetAnalytics); return row ? <div className={styles.assetDetailPanel}><div className={styles.panelTitle}><b>{row.name}</b><HelpTip text="Здесь собрана информация только по выбранному байку." /></div><div className={styles.assetDetailGrid}><span>Выручка <b>{currency(row.income)}</b></span><span>Расходы <b>{currency(row.expenses)}</b></span><span>Прибыль <b>{currency(row.profit)}</b></span><span>Простой <b>{row.monthlyIdle ?? 0} дн.</b></span></div><div className={styles.assetDetailBookings}>{assetBookings.length ? assetBookings.map(item => <div key={item.id}><span>{item.clientName}</span><small>{format(new Date(item.startDate), "d MMM", { locale: ru })} — {format(new Date(item.endDate), "d MMM", { locale: ru })}</small><b>{currency(item.totalPrice)}</b></div>) : <span>Бронирований по этому объекту нет</span>}</div></div> : null; })()}
        {(!analytics.byAsset || analytics.byAsset.length === 0) && <div className={styles.emptyState}><b>Недостаточно данных</b><span>Создайте объект и бронирование, чтобы увидеть загрузку и прибыль.</span></div>}
      </div>
    </section>}
    {tab === "profile" && <section className={styles.content}>
      <div className={styles.profileSectionHeader}><div><p className={styles.eyebrow}>УПРАВЛЕНИЕ</p><h2>Мой бизнес</h2></div><div className={styles.headerActions}><label className={styles.scaleControl}>Календарь <select value={calendarScale} onChange={e => { setCalendarScale(e.target.value); window.localStorage.setItem("rp_calendar_scale", e.target.value); }}><option value="compact">Компактный</option><option value="normal">Обычный</option><option value="large">Крупный</option></select></label> <button className={styles.secondaryButtonSmall} onClick={async () => { setLoggingOut(true); await fetch("/api/auth/logout", { method: "POST" }); window.setTimeout(() => window.location.reload(), 500); }}>Выйти</button><span className={styles.helpWrap}><button className={styles.primaryButton} onClick={() => { setEditingAsset(null); setModal("asset"); }}><Plus size={16} /> Добавить</button><HelpTip text="Добавляет байк в парк. После сохранения он появляется в календаре и списке брони." /></span></div></div>
      <div className={styles.profileSearch}><div className={styles.searchBox}><Search size={18} /><input placeholder="Поиск по байкам, партнёрам и команде" value={profileSearch} onChange={e => setProfileSearch(e.target.value)} /><HelpTip text="Поиск по названию, телефону, email или имени. Это удобно для большого парка и сотен партнёров." /></div></div><div className={styles.profileGroup}><div className={styles.profileGroupTitle}><b>Команда и права <HelpTip text="Управление менеджерами, бухгалтерами и доступами." /></b><button className={styles.linkButton} onClick={() => setModal("team")}>+ Добавить</button></div>{team.filter(member => `${member.name} ${member.phone || ""} ${member.email || ""} ${member.role}`.toLowerCase().includes(profileSearch.toLowerCase())).map(member => <div className={styles.manageRow} key={member.id}><div><b>{member.name}</b><span>{member.role} · {member.phone || "без телефона"} · {member.email || "без email"}{member.telegramId ? ` · Telegram ${member.telegramId}` : ""}</span></div><div className={styles.rowActions}><button className={styles.editButton} onClick={() => { setEditingTeam(member); setModal("team"); }}>Изменить</button><button className={styles.deleteButton} onClick={async () => { if (confirm(`Удалить ${member.name}?`)) { await api("/api/team", { method: "DELETE", body: JSON.stringify({ id: member.id }) }); await refresh(); } }}>Удалить</button></div></div>)}{team.length === 0 && <span className={styles.mutedText}>Менеджеров пока нет</span>}</div><div className={styles.profileGroup}><div className={styles.profileGroupTitle}><b>Партнёры <HelpTip text="Партнёры находятся в отдельном списке. Используйте поиск выше." /></b><button className={styles.linkButton} onClick={() => setModal("partner")}>+ Добавить</button></div>{partners.filter(partner => `${partner.name} ${partner.contactName || ""} ${partner.phone || ""} ${partner.email || ""}`.toLowerCase().includes(profileSearch.toLowerCase())).map(partner => <div className={styles.manageRow} key={partner.id}><div><b>{partner.name}</b><span>{partner.contactName || "Без контакта"} · {partner.phone || "Нет телефона"} · {partner.email || "без email"} · {partner.commissionValue}{partner.commissionType === "PERCENT" ? "%" : " ₫"}</span></div><div className={styles.contactActions}>{partner.phone && <a title="Позвонить" href={`tel:${partner.phone}`}><Phone size={15} /></a>}{partner.phone && partner.contactChannel === "WHATSAPP" && <a title="WhatsApp" target="_blank" rel="noreferrer" href={`https://wa.me/${partner.phone.replace(/\D/g, "")}`}><MessageCircle size={15} /></a>}{partner.phone && partner.contactChannel === "TELEGRAM" && <a title="Telegram" target="_blank" rel="noreferrer" href={`https://t.me/${partner.phone.replace(/^@/, "")}`}><Send size={15} /></a>}<button className={styles.editButton} onClick={() => { setEditingPartner(partner); setModal("partner"); }}>Изменить</button><button className={styles.deleteButton} onClick={async () => { if (confirm(`Удалить партнёра ${partner.name}?`)) { await api("/api/partners", { method: "DELETE", body: JSON.stringify({ id: partner.id }) }); await refresh(); } }}>Удалить</button></div></div>)}{partners.length === 0 && <span className={styles.mutedText}>Партнёров пока нет</span>}</div>
      <div className={`${styles.profileGroup} ${styles.fleetGroup}`}><div className={styles.profileGroupTitle}><b>Мой автопарк <HelpTip text="Все байки и автомобили. Поиск выше скрывает остальные записи." /></b><span>{assets.length} объектов</span></div>{assets.filter(asset => `${asset.name} ${asset.category} ${asset.status}`.toLowerCase().includes(profileSearch.toLowerCase())).map(asset => <div className={styles.manageRow} draggable onDragStart={() => setDragAsset(asset.id)} onDragOver={e => e.preventDefault()} onDrop={() => void reorder(asset.id)} key={asset.id}><div><b><AssetLabel name={asset.name} /></b><span>{asset.category === "SCOOTER" ? "Скутер" : asset.category === "MOTORCYCLE" ? "Мотоцикл" : asset.category} · {asset.status}</span></div><div className={styles.rowActions}><button className={styles.editButton} onClick={() => { setEditingAsset(asset); setModal("asset"); }}>Редактировать</button><button className={styles.deleteButton} onClick={async () => { if (confirm(`Удалить ${asset.name}?`)) { await api("/api/assets", { method: "DELETE", body: JSON.stringify({ id: asset.id }) }); await refresh(); } }}>Удалить</button></div></div>)}{assets.length === 0 && <div className={styles.emptyState}><b>Автопарк пуст</b><span>Нажмите «Добавить» и сохраните первый байк.</span></div>}</div>
      
    </section>}
    <nav className={styles.bottomNav}>{([ ["calendar", CalendarDays, "Календарь"], ["bookings", LayoutDashboard, "Брони"], ["analytics", CircleDollarSign, "Аналитика"], ["profile", UserRound, "Профиль"] ] as const).map(([key, Icon, label]) => <button key={key} className={tab === key ? styles.navActive : ""} onClick={() => setTab(key)}><Icon size={20} /><span>{label}</span></button>)}</nav>
    {modal === "booking" && <BookingModal key={`${bookingSeed?.assetId ?? "new"}-${bookingSeed?.startDate ?? "today"}`} assets={assets} partners={partners} initialAssetId={bookingSeed?.assetId} initialDate={bookingSeed?.startDate} initialEndDate={bookingSeed?.endDate} api={api} onClose={closeModal} onDone={async message => { closeModal(); setToast(message); await refresh(); }} />}
    {modal === "asset" && <AssetModal key={editingAsset?.id ?? "new"} asset={editingAsset} api={api} onClose={() => { setEditingAsset(null); closeModal(); }} onDone={async message => { setEditingAsset(null); closeModal(); setToast(message); await refresh(); }} />}
    {modal === "payment" && selectedBooking && <PaymentModal booking={selectedBooking} api={api} onClose={closeModal} onDone={async message => { closeModal(); setToast(message); await refresh(); }} currency={currency} />}
    {modal === "partner" && <PartnerModal partner={editingPartner} api={api} onClose={() => { setEditingPartner(null); closeModal(); }} onDone={async message => { setEditingPartner(null); closeModal(); setToast(message); await refresh(); }} />}
    {modal === "team" && <TeamModal member={editingTeam} api={api} onClose={() => { setEditingTeam(null); closeModal(); }} onDone={async message => { setEditingTeam(null); closeModal(); setToast(message); await refresh(); }} />}
    {loggingOut && <div className={styles.logoutScreen}><img src="/karmarent-logo.png" alt="RideFlow Rent" /><b>До встречи</b><span>Сеанс завершается…</span></div>}
    {toast && <div className={styles.toast}>{toast}</div>}
  </main>;
}
function LoginPanel({ api, onDone }: { api: (path: string, options?: RequestInit) => Promise<any>; onDone: () => Promise<void> }) { const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [showPassword, setShowPassword] = useState(false); const [error, setError] = useState(""); return <div className={styles.loginPanel}><div className={styles.loginCard}><img className={styles.loginLogo} src="/karmarent-logo.png" alt="RideFlow Rent" /><p className={styles.eyebrow}>RIDEFLOW RENT</p><h2>Вход в приложение</h2><p>Можно работать через обычный браузер. Telegram остаётся быстрым входом внутри Mini App.</p><label>Email<input type="email" autoComplete="off" value={email} onChange={e => setEmail(e.target.value)} placeholder="owner@example.com" /></label><label>Пароль<div className={styles.passwordField}><input type={showPassword ? "text" : "password"} autoComplete="new-password" value={password} onChange={e => setPassword(e.target.value)} /><button type="button" className={styles.showPasswordButton} onClick={() => setShowPassword(value => !value)}>{showPassword ? "Скрыть" : "Показать"}</button></div></label>{error && <p className={styles.formError}>{error}</p>}<button className={styles.submitButton} onClick={async e => { e.preventDefault(); setError(""); try { await api("/api/auth/login", { method: "POST", body: JSON.stringify({ email: email.trim(), password }) }); await onDone(); } catch (err) { setError(err instanceof Error ? err.message : "Не удалось войти"); } }}>Войти</button></div></div>; }
function HelpTip({ text }: { text: string }) { const [open, setOpen] = useState(false); return <span className={styles.helpTip}><button type="button" className={styles.helpButton} aria-label="Подсказка" onClick={() => setOpen(value => !value)}>?</button>{open && <span className={styles.helpPopover}><button type="button" className={styles.helpClose} aria-label="Закрыть подсказку" onClick={() => setOpen(false)}>×</button><span>{text}</span></span>}</span>; }
function Metric({ title, value, icon, accent }: { title: string; value: string; icon: React.ReactNode; accent: string }) { const help = title.includes("Выручка") ? "Фактически полученные платежи по аренде." : title.includes("Ожидается") ? "Сумма, которую должны получить по активным бронированиям." : title.includes("Расходы") ? "Расходы, связанные с обслуживанием и работой парка." : title.includes("комиссия") ? "Сумма комиссии менеджера по его проценту от полученных платежей." : title.includes("Объектов") ? "Количество объектов, доступных менеджеру в парке." : "Доходы минус расходы за выбранный период."; return <div className={styles.metric}><div className={styles.metricTop}><div className={`${styles.metricIcon} ${styles[accent]}`}>{icon}</div><HelpTip text={help} /></div><span>{title}</span><strong>{value}</strong></div>; }
function ModalFrame({ title, eyebrow, children, onClose }: { title: string; eyebrow: string; children: React.ReactNode; onClose: () => void }) { return <div className={styles.modalBackdrop} onClick={onClose}><form className={styles.modal} onClick={e => e.stopPropagation()}><div className={styles.modalHeader}><div><p className={styles.eyebrow}>{eyebrow}</p><h2>{title}</h2></div><button type="button" onClick={onClose}><X size={18} /></button></div>{children}</form></div>; }
function BookingModal({ assets, partners, initialAssetId, initialDate, initialEndDate, api, onClose, onDone }: { assets: Asset[]; partners: Partner[]; initialAssetId?: string; initialDate?: string; initialEndDate?: string; api: (path: string, options?: RequestInit) => Promise<any>; onClose: () => void; onDone: (message: string) => Promise<void> }) { const [form, setForm] = useState({ assetId: initialAssetId ?? assets[0]?.id ?? "", partnerId: "", clientName: "", clientPhone: "", startDate: initialDate ?? format(new Date(), "yyyy-MM-dd"), endDate: initialEndDate ?? format(addDays(new Date(), 1), "yyyy-MM-dd"), startTime: format(new Date(), "HH:mm"), endTime: format(new Date(), "HH:mm"), dailyRate: "", paidAmount: "0", depositAmount: "100", depositCurrency: "₫", passportPhoto: true, mileageLimitPerDay: "100", phoneHolder: "Premium", helmetCount: "2", mileageAtHandover: "", fuelLevel: "", notes: "" }); const [error, setError] = useState(""); const [pendingMedia, setPendingMedia] = useState<Array<{ filename: string; dataUrl: string }>>([]); const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({}); const set = (key: string, value: string | boolean) => { setFieldErrors(current => ({ ...current, [key]: "" })); setForm(prev => ({ ...prev, [key]: value })); }; const daysCount = Math.max(1, Math.ceil((new Date(`${form.endDate}T${form.endTime}`).getTime() - new Date(`${form.startDate}T${form.startTime}`).getTime()) / 86400000)); const total = daysCount * Number(form.dailyRate || 0); return <ModalFrame eyebrow="НОВАЯ БРОНЬ" title="Данные аренды" onClose={onClose}><div className={styles.bookingForm}>{initialAssetId ? <div className={styles.selectedAsset}><span>Байк из календаря</span><b><AssetLabel name={assets.find(a => a.id === form.assetId)?.name || "Объект"} /></b><HelpTip text="Байк уже выбран нажатием на строку календаря. Здесь менять его не нужно." /></div> : <label>Объект<select required value={form.assetId} onChange={e => { set("assetId", e.target.value); const a = assets.find(item => item.id === e.target.value); if (a && Number(a.dailyRate) > 0) set("dailyRate", String(a.dailyRate)); else set("dailyRate", ""); }}>{assets.length === 0 && <option value="">Нет объектов</option>}{assets.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}</select></label>}<div className={styles.compactContactGrid}><label>Партнёр <HelpTip text="Партнёр связывает бронь, акт и будущий отчёт. Можно оставить пустым." /><select value={form.partnerId} onChange={e => set("partnerId", e.target.value)}><option value="">Без партнёра</option>{partners.map(partner => <option key={partner.id} value={partner.id}>{partner.name}</option>)}</select></label><label className={fieldErrors.clientName ? styles.invalidField : ""}>Имя клиента<input required value={form.clientName} onChange={e => set("clientName", e.target.value)} placeholder="Например, Алексей" />{fieldErrors.clientName && <small className={styles.fieldError}>{fieldErrors.clientName}</small>}</label><label className={fieldErrors.clientPhone ? styles.invalidField : ""}>{form.clientPhone.trim().startsWith("@") || form.clientPhone.includes("t.me/") ? "Telegram" : "Телефон / Telegram"}<input required value={form.clientPhone} onChange={e => set("clientPhone", e.target.value)} placeholder="+84... или @telegram" />{form.clientPhone.trim() && <span className={styles.contactQuickActions}>{form.clientPhone.trim().startsWith("@") || form.clientPhone.includes("t.me/") ? <a href={`https://t.me/${form.clientPhone.trim().replace(/^@/, "").replace(/^.*t.me\//, "")}`} target="_blank" rel="noreferrer"><Send size={12} /> Telegram</a> : <><a href={`https://wa.me/${form.clientPhone.replace(/\D/g, "")}`} target="_blank" rel="noreferrer"><MessageCircle size={12} /> WhatsApp</a><a href={`https://t.me/+${form.clientPhone.replace(/\D/g, "")}`} target="_blank" rel="noreferrer"><Send size={12} /> Telegram</a></>}</span>}{fieldErrors.clientPhone && <small className={styles.fieldError}>{fieldErrors.clientPhone}</small>}</label></div><div className={styles.formGrid}><label>Фото паспорта<select value={form.passportPhoto ? "yes" : "no"} onChange={e => set("passportPhoto", e.target.value === "yes")}><option value="no">Нет</option><option value="yes">Есть</option></select></label><label>Лимит км/сутки<input type="number" min="0" value={form.mileageLimitPerDay} onChange={e => set("mileageLimitPerDay", e.target.value)} placeholder="100" /></label></div><div className={styles.formGrid}><label>Держатель телефона<input value={form.phoneHolder} onChange={e => set("phoneHolder", e.target.value)} placeholder="Premium" /></label><label>Шлемы<input type="number" min="0" value={form.helmetCount} onChange={e => set("helmetCount", e.target.value)} placeholder="2" /></label></div><div className={styles.formGrid}><label>Пробег при выдаче<input type="number" min="0" value={form.mileageAtHandover} onChange={e => set("mileageAtHandover", e.target.value)} placeholder="67206" /></label><label>Бензин<input value={form.fuelLevel} onChange={e => set("fuelLevel", e.target.value)} placeholder="1/6" /></label></div><div className={styles.formGrid}><label>Начало<input type="date" required value={form.startDate} onChange={e => set("startDate", e.target.value)} /><input type="time" value={form.startTime} onChange={e => set("startTime", e.target.value)} /></label><label>Окончание<input type="date" required value={form.endDate} onChange={e => set("endDate", e.target.value)} /><input type="time" value={form.endTime} onChange={e => set("endTime", e.target.value)} /></label></div><label className={styles.daysControl}>Количество суток <HelpTip text="Сутки считаются от времени выдачи до такого же времени возврата. Например, 7.10 12:00 — 9.10 12:00 = 2 суток." /><select value={daysCount} onChange={e => { const value = Math.max(1, Number(e.target.value) || 1); set("endDate", format(addDays(new Date(form.startDate), value), "yyyy-MM-dd")); }}>{Array.from({ length: 365 }, (_, index) => index + 1).map(value => <option key={value} value={value}>{value} суток</option>)}</select></label><div className={`${styles.formGrid} ${styles.bookingMoneyGrid}`}><label className={fieldErrors.dailyRate ? styles.invalidField : ""}>Ставка/день<input type="number" min="0" required value={form.dailyRate} onChange={e => set("dailyRate", e.target.value)} /></label>{fieldErrors.dailyRate && <small className={styles.fieldError}>{fieldErrors.dailyRate}</small>}<label>Депозит<input inputMode="decimal" value={form.depositAmount} onChange={e => set("depositAmount", e.target.value.replace(/[^0-9.,]/g, ""))} /></label><label>Валюта<select value={form.depositCurrency} onChange={e => set("depositCurrency", e.target.value)}><option value="₫">₫</option><option value="$">$</option><option value="OTHER">Другая / эквивалент</option></select>{form.depositCurrency === "OTHER" && <input className={styles.otherCurrency} value={form.notes.match(/\[Валюта:([^\]]+)\]/)?.[1] || ""} onChange={e => set("notes", `${form.notes.replace(/\[Валюта:[^\]]+\]/, "").trim()}${e.target.value ? ` [Валюта:${e.target.value}]` : ""}`)} placeholder="Эквивалент: USD, EUR..." />}</label></div><div className={styles.calculated}>Дней: <b>{daysCount}</b> · Итого: <b>{total.toLocaleString("vi-VN")} ₫</b></div><label>Примечание <HelpTip text="Запишите дополнительные условия аренды, залога или договорённости с клиентом." /><textarea value={form.notes} onChange={e => set("notes", e.target.value)} placeholder="Дополнительные условия" /></label><div className={styles.bookingMediaPicker}><div><b>Фото и документы</b><HelpTip text="Выберите фото из телефона или откройте камеру. Файлы сохранятся в карточке брони после создания." /></div><label className={styles.cameraButton}>Камера<input type="file" accept="image/*" capture="environment" multiple onChange={async e => { const files = Array.from(e.target.files || []); const loaded = await Promise.all(files.map(file => new Promise<{ filename: string; dataUrl: string } | null>(resolve => { if (file.size > 6_000_000) { setError(`Файл ${file.name} больше 6 МБ`); resolve(null); return; } const reader = new FileReader(); reader.onload = () => resolve({ filename: file.name, dataUrl: String(reader.result || "") }); reader.onerror = () => resolve(null); reader.readAsDataURL(file); }))); setPendingMedia(current => [...current, ...loaded.filter((item): item is { filename: string; dataUrl: string } => Boolean(item))]); e.currentTarget.value = ""; }} /></label><label className={styles.cameraButton}>Файлы<input type="file" accept="image/*,.pdf" multiple onChange={async e => { const files = Array.from(e.target.files || []); const loaded = await Promise.all(files.map(file => new Promise<{ filename: string; dataUrl: string } | null>(resolve => { if (file.size > 6_000_000) { setError(`Файл ${file.name} больше 6 МБ`); resolve(null); return; } const reader = new FileReader(); reader.onload = () => resolve({ filename: file.name, dataUrl: String(reader.result || "") }); reader.onerror = () => resolve(null); reader.readAsDataURL(file); }))); setPendingMedia(current => [...current, ...loaded.filter((item): item is { filename: string; dataUrl: string } => Boolean(item))]); e.currentTarget.value = ""; }} /></label><span className={styles.videoFuture}>Видео — скоро</span>{pendingMedia.length > 0 && <span className={styles.mediaCount}>Выбрано: {pendingMedia.length}</span>}</div>{error && <p className={styles.formError}>{error}</p>}<button className={styles.submitButton} disabled={!form.assetId} onClick={async e => { e.preventDefault(); const nextErrors: Record<string, string> = {}; if (form.clientName.trim().length < 2) nextErrors.clientName = "Введите имя клиента (минимум 2 символа)"; if (form.clientPhone.trim().length < 7) nextErrors.clientPhone = "Введите телефон или Telegram минимум из 7 символов"; if (!form.dailyRate || Number(form.dailyRate) <= 0) nextErrors.dailyRate = "Укажите ставку за сутки"; if (Object.keys(nextErrors).length) { setFieldErrors(nextErrors); setError("Проверьте выделенные поля"); return; } try { const created = await api("/api/bookings", { method: "POST", body: JSON.stringify({ ...form, partnerId: form.partnerId || undefined, dailyRate: Number(form.dailyRate), totalPrice: total, paidAmount: Number(form.paidAmount), depositAmount: Number(form.depositAmount), notes: form.notes, mileageLimitPerDay: form.mileageLimitPerDay === "" ? undefined : Number(form.mileageLimitPerDay), helmetCount: form.helmetCount === "" ? undefined : Number(form.helmetCount), mileageAtHandover: form.mileageAtHandover === "" ? undefined : Number(form.mileageAtHandover), status: "CONFIRMED" }) }); for (const media of pendingMedia) await api("/api/bookings/media", { method: "POST", body: JSON.stringify({ bookingId: created.id, filename: media.filename, dataUrl: media.dataUrl, kind: media.dataUrl.startsWith("data:application/pdf") ? "DOCUMENT" : "PHOTO" }) }); await onDone(pendingMedia.length ? `Бронь создана, файлов сохранено: ${pendingMedia.length}` : "Бронь создана"); } catch (err) { setError(err instanceof Error ? err.message : "Не удалось создать бронь"); } }}>Создать бронь</button></div></ModalFrame>; }
function AssetModal({ asset, api, onClose, onDone }: { asset?: Asset | null; api: (path: string, options?: RequestInit) => Promise<any>; onClose: () => void; onDone: (message: string) => Promise<void> }) { const [form, setForm] = useState({ name: asset?.name ?? "", category: asset?.category ?? "SCOOTER", currentMileage: asset?.currentMileage ? String(asset.currentMileage) : "", oilChangeMileage: asset?.oilChangeMileage ? String(asset.oilChangeMileage) : "", variatorServiceMileage: asset?.variatorServiceMileage ? String(asset.variatorServiceMileage) : "", lastServiceDate: asset?.lastServiceDate ? asset.lastServiceDate.slice(0, 10) : "", serviceNote: asset?.serviceNote ?? "", rentalConditions: asset?.rentalConditions ?? "" }); const [error, setError] = useState(""); const set = (key: string, value: string) => setForm(prev => ({ ...prev, [key]: value })); return <ModalFrame eyebrow="МОЙ АВТОПАРК" title={asset ? "Редактировать объект" : "Новый объект"} onClose={onClose}><label>Название байка<input autoComplete="off" required value={form.name} onChange={e => set("name", e.target.value)} placeholder="Priti Elite 50cc (75)" /></label><label>Категория<select value={form.category} onChange={e => set("category", e.target.value)}><option value="SCOOTER">Скутер</option><option value="MOTORCYCLE">Мотоцикл</option><option value="CAR">Автомобиль</option><option value="REAL_ESTATE">Недвижимость</option><option value="OTHER">Другое</option></select></label><div className={styles.serviceCompactGrid}><label>Текущий пробег<input type="number" min="0" value={form.currentMileage} onChange={e => set("currentMileage", e.target.value)} placeholder="67206" /></label><label>Масло на пробеге<input type="number" min="0" value={form.oilChangeMileage} onChange={e => set("oilChangeMileage", e.target.value)} placeholder="70000" /></label><label>Вариатор на пробеге<input type="number" min="0" value={form.variatorServiceMileage} onChange={e => set("variatorServiceMileage", e.target.value)} placeholder="75000" /></label><label>Последнее обслуживание<input type="date" value={form.lastServiceDate} onChange={e => set("lastServiceDate", e.target.value)} /></label></div><label>Примечание по обслуживанию <HelpTip text="Например: заменить масло, проверить ремень вариатора, тормоза, шины, свет, аккумулятор и крепления." /><input value={form.serviceNote} onChange={e => set("serviceNote", e.target.value)} placeholder="Масло, ремень, тормоза…" /></label><label>Условия именно для этого байка <HelpTip text="Эти условия попадут в PDF-акт выбранного байка. Если оставить пустым, будут использованы стандартные условия Karma Rent." /><textarea rows={4} value={form.rentalConditions} onChange={e => set("rentalConditions", e.target.value)} placeholder="Ограничения, особенности и условия этого байка" /></label>{error && <p className={styles.formError}>{error}</p>}<button className={styles.submitButton} onClick={async e => { e.preventDefault(); try { await api("/api/assets", { method: asset ? "PATCH" : "POST", body: JSON.stringify({ name: form.name, category: form.category, currentMileage: form.currentMileage === "" ? undefined : Number(form.currentMileage), oilChangeMileage: form.oilChangeMileage === "" ? undefined : Number(form.oilChangeMileage), variatorServiceMileage: form.variatorServiceMileage === "" ? undefined : Number(form.variatorServiceMileage), lastServiceDate: form.lastServiceDate || undefined, serviceNote: form.serviceNote, rentalConditions: form.rentalConditions, ...(asset ? { id: asset.id } : {}) }) }); await onDone(asset ? "Объект обновлён" : "Объект добавлен"); } catch (err) { setError(err instanceof Error ? err.message : "Не удалось сохранить объект"); } }}>{asset ? "Сохранить изменения" : "Добавить объект"}</button></ModalFrame>; }
function PartnerModal({ partner, api, onClose, onDone }: { partner?: Partner | null; api: (path: string, options?: RequestInit) => Promise<any>; onClose: () => void; onDone: (message: string) => Promise<void> }) { const [form,setForm]=useState({name:partner?.name??"",contactName:partner?.contactName??"",phone:partner?.phone??"",email:partner?.email??"",contactChannel:partner?.contactChannel??"PHONE",commissionType:partner?.commissionType??"PERCENT",commissionValue:partner?String(partner.commissionValue):""}); const [error,setError]=useState(""); const set=(k:string,v:string)=>setForm(x=>({...x,[k]:v})); return <ModalFrame eyebrow="ПАРТНЁРЫ" title={partner?"Редактировать партнёра":"Новый партнёр"} onClose={onClose}><label>Название<input required value={form.name} onChange={e=>set("name",e.target.value)} /></label><label>Контактное лицо<input value={form.contactName} onChange={e=>set("contactName",e.target.value)} /></label><label>Телефон или username<input value={form.phone} onChange={e=>set("phone",e.target.value)} /></label><label>Email<input type="email" value={form.email} onChange={e=>set("email",e.target.value)} /></label><label>Канал связи<select value={form.contactChannel} onChange={e=>set("contactChannel",e.target.value)}><option value="PHONE">Обычный телефон</option><option value="WHATSAPP">WhatsApp</option><option value="TELEGRAM">Telegram</option></select></label><div className={styles.formGrid}><label>Тип комиссии<select value={form.commissionType} onChange={e=>set("commissionType",e.target.value)}><option value="PERCENT">Процент</option><option value="FIXED">Фиксированная</option></select></label><label>Комиссия<input type="number" min="0" value={form.commissionValue} onChange={e=>set("commissionValue",e.target.value)} /></label></div>{error&&<p className={styles.formError}>{error}</p>}<button className={styles.submitButton} onClick={async e=>{e.preventDefault();try{await api("/api/partners",{method:partner?"PATCH":"POST",body:JSON.stringify({...form,id:partner?.id,commissionValue:Number(form.commissionValue)})});await onDone(partner?"Партнёр обновлён":"Партнёр добавлен")}catch(err){setError(err instanceof Error?err.message:"Не удалось сохранить партнёра")}}}>{partner?"Сохранить изменения":"Сохранить партнёра"}</button></ModalFrame>; }
function TeamModal({ member, api, onClose, onDone }: { member?: TeamMember | null; api: (path: string, options?: RequestInit) => Promise<any>; onClose: () => void; onDone: (message: string) => Promise<void> }) { const [form,setForm]=useState({name:member?.name??"",phone:member?.phone??"",telegramId:member?.telegramId??"",email:member?.email??"",password:"",commissionPercent:member?String(member.commissionPercent):"",role:member?.role??"MANAGER"}); const [error,setError]=useState(""); const set=(k:string,v:string)=>setForm(x=>({...x,[k]:v})); return <ModalFrame eyebrow="КОМАНДА" title={member?"Редактировать участника":"Добавить менеджера"} onClose={onClose}><label>Имя<input required value={form.name} onChange={e=>set("name",e.target.value)} /></label><label>Телефон<input type="tel" value={form.phone} onChange={e=>set("phone",e.target.value)} /></label><label>Telegram ID<input inputMode="numeric" value={form.telegramId} onChange={e=>set("telegramId",e.target.value.replace(/\D/g,""))} /></label><label>Email<input type="email" value={form.email} onChange={e=>set("email",e.target.value)} /></label><label>Пароль{member&&<small className={styles.mutedText}> — пусто = не менять</small>}<input type="password" required={!member} minLength={6} value={form.password} onChange={e=>set("password",e.target.value)} /></label><label>Процент менеджера<input type="number" min="0" max="100" value={form.commissionPercent} onChange={e=>set("commissionPercent",e.target.value)} /></label><label>Роль<select value={form.role} onChange={e=>set("role",e.target.value)}><option value="MANAGER">Менеджер</option><option value="ADMIN">Администратор</option><option value="ACCOUNTANT">Бухгалтер</option></select></label>{error&&<p className={styles.formError}>{error}</p>}<button className={styles.submitButton} onClick={async e=>{e.preventDefault();try{await api("/api/team",{method:member?"PATCH":"POST",body:JSON.stringify({...form,id:member?.id,commissionPercent:Number(form.commissionPercent||0),permissions:{assets:true,bookings:true,analytics:true,expenses:false,team:form.role==="ADMIN",reports:form.role!=="MANAGER"}})});await onDone(member?"Участник обновлён":"Участник добавлен")}catch(err){setError(err instanceof Error?err.message:"Не удалось сохранить участника")}}}>{member?"Сохранить изменения":"Сохранить участника"}</button></ModalFrame>; }
function PaymentModal({ booking, api, onClose, onDone, currency }: { booking: Booking; api: (path: string, options?: RequestInit) => Promise<any>; onClose: () => void; onDone: (message: string) => Promise<void>; currency: (value: string | number) => string }) { const [amount, setAmount] = useState(""); const [error, setError] = useState(""); const [actUrl, setActUrl] = useState(""); const [actPartner, setActPartner] = useState(""); const [audit, setAudit] = useState<Array<{ id: string; actorName: string; actorRole?: string; reason?: string; createdAt: string }>>([]); const [media, setMedia] = useState<Array<{ id: string; filename?: string; dataUrl: string; kind: string }>>([]); const [reason, setReason] = useState(""); const [startDate, setStartDate] = useState(booking.startDate.slice(0, 10)); const [endDate, setEndDate] = useState(booking.endDate.slice(0, 10)); const [startTime, setStartTime] = useState(booking.startTime || "12:00"); const [endTime, setEndTime] = useState(booking.endTime || "12:00"); const [dailyRate, setDailyRate] = useState(String(booking.dailyRate || "0")); const [extensionDays, setExtensionDays] = useState("1"); useEffect(() => { void api(`/api/audit?entityId=${booking.id}`).then(setAudit).catch(() => setAudit([])); void api(`/api/bookings/media?bookingId=${booking.id}`).then(setMedia).catch(() => setMedia([])); }, [api, booking.id]); const days = Math.max(1, Math.ceil((new Date(`${endDate}T${endTime}`).getTime() - new Date(`${startDate}T${startTime}`).getTime()) / 86400000)); const savePeriod = async (nextEnd = endDate) => { try { await api("/api/bookings", { method: "PATCH", body: JSON.stringify({ id: booking.id, startDate, endDate: nextEnd, startTime, endTime, dailyRate: Number(dailyRate), reason }) }); await onDone("Период брони обновлён"); } catch (err) { setError(err instanceof Error ? err.message : "Не удалось обновить период"); } }; const createAct = async () => { try { const result = await api("/api/acts", { method: "POST", body: JSON.stringify({ bookingId: booking.id, partnerName: actPartner }) }); setActUrl(result.url); await navigator.clipboard?.writeText(result.url); setError("Ссылка на акт скопирована"); } catch (err) { setError(err instanceof Error ? err.message : "Не удалось создать акт"); } }; return <ModalFrame eyebrow="БРОНИРОВАНИЕ" title={booking.clientName} onClose={onClose}><div className={styles.detailBox}><span>{booking.asset?.name}</span><b>{currency(booking.totalPrice)}</b><small>Сейчас: {booking.startDate.slice(0, 10)} — {booking.endDate.slice(0, 10)} · {booking.startTime || "12:00"}–{booking.endTime || "12:00"}</small></div><div className={styles.formGrid}><label>Выдача<input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} /><input type="time" value={startTime} onChange={e => setStartTime(e.target.value)} /></label><label>Сдача<input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} /><input type="time" value={endTime} onChange={e => setEndTime(e.target.value)} /></label></div><label>Ставка за сутки <HelpTip text="Изменение ставки меняет общую сумму брони и обязательно фиксируется в журнале." /><input type="number" min="0" value={dailyRate} onChange={e => setDailyRate(e.target.value)} /></label><label>Причина изменения <HelpTip text="Обязательно укажите, почему изменили дату, время или продлили бронь. Это попадёт в журнал контроля." /><input value={reason} onChange={e => setReason(e.target.value)} placeholder="Например: клиент продлил аренду" /></label><div className={styles.calculated}>Дней: <b>{days}</b> · Новая сумма: <b>{currency(days * Number(dailyRate || 0))}</b></div><div className={styles.buttonRow}><button className={styles.secondaryButton} type="button" onClick={() => void savePeriod()}>Сохранить изменения <HelpTip text="Сохраняет новые даты и время брони. Причина записывается в журнал контроля." /></button><div className={styles.extendBox}><label>Продлить на <HelpTip text="Выберите, на сколько дополнительных суток продлить бронь. После выбора нажмите кнопку продления." /><input inputMode="numeric" value={extensionDays} onChange={e => setExtensionDays(e.target.value.replace(/\D/g, "").slice(0, 3))} placeholder="Например, 10" /></label><button className={styles.secondaryButton} type="button" onClick={() => { const next = format(addDays(new Date(`${endDate}T${endTime}`), Number(extensionDays)), "yyyy-MM-dd"); setEndDate(next); }}>Продлить бронь</button></div></div><div className={styles.mediaBox}><div className={styles.mediaHeader}><b>Фото и документы</b><HelpTip text="Фотографии хранятся в базе данных этой брони и доступны только вашей команде." /><label className={styles.mediaUpload}>Добавить фото<input type="file" accept="image/*,.pdf" capture="environment" multiple onChange={async e => { const files = Array.from(e.target.files || []); for (const file of files) { const reader = new FileReader(); reader.onload = async () => { try { const row = await api("/api/bookings/media", { method: "POST", body: JSON.stringify({ bookingId: booking.id, filename: file.name, dataUrl: reader.result }) }); setMedia(current => [...current, row]); } catch (err) { setError(err instanceof Error ? err.message : "Не удалось сохранить фото"); } }; reader.readAsDataURL(file); } e.currentTarget.value = ""; }} /></label></div>{media.length > 0 ? <div className={styles.mediaCarousel}>{media.map(item => <figure key={item.id}>{item.dataUrl.startsWith("data:application/pdf") ? <a className={styles.documentLink} href={item.dataUrl} target="_blank" rel="noreferrer">PDF<br />Открыть</a> : <img src={item.dataUrl} alt={item.filename || "Фото брони"} />}<figcaption>{item.filename || "Файл"}</figcaption></figure>)}</div> : <small className={styles.mutedText}>Фото пока не загружены</small>}</div>{audit.length > 0 && <div className={styles.auditPanel}><b>История изменений</b>{audit.map(item => <div className={styles.auditItem} key={item.id}><strong>{item.actorName} · {item.actorRole || ""}</strong><small>{new Date(item.createdAt).toLocaleString("ru-RU")}</small><span>Причина: {item.reason || "не указана"}</span></div>)}</div>}<button className={styles.deleteButton} type="button" onClick={async () => { if (!window.confirm("Переместить бронь в архив на 14 дней?")) return; try { await api(`/api/bookings?id=${booking.id}`, { method: "DELETE" }); await onDone("Бронь перемещена в архив на 14 дней"); } catch (err) { setError(err instanceof Error ? err.message : "Не удалось архивировать бронь"); } }}>Удалить бронь в архив</button><label>Партнёр в акте <HelpTip text="Напишите партнёра вручную. Это имя будет напечатано в акте передачи." /><input value={actPartner} onChange={e => setActPartner(e.target.value)} placeholder="Например: Nguyen Travel" /></label><button className={styles.secondaryButton} type="button" onClick={createAct}>Акт передачи · создать</button>{actUrl && <><a className={styles.actLink} href={actUrl} target="_blank" rel="noreferrer">Открыть акт</a><button type="button" className={styles.secondaryButton} onClick={async () => { await navigator.clipboard?.writeText(actUrl); setError("Ссылка на акт скопирована"); }}>Скопировать ссылку</button></>}<label>Сумма платежа<input type="number" min="1" value={amount} onChange={e => setAmount(e.target.value)} placeholder="100" /></label>{error && <p className={styles.formError}>{error}</p>}<button className={styles.submitButton} onClick={async e => { e.preventDefault(); try { await api("/api/payments", { method: "POST", body: JSON.stringify({ bookingId: booking.id, amount: Number(amount), paymentType: "RENTAL", paymentMethod: "CASH" }) }); await onDone("Платёж добавлен"); } catch (err) { setError(err instanceof Error ? err.message : "Не удалось добавить платёж"); } }}>Добавить оплату</button></ModalFrame>; }
